/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { CNF, EncodedCNF, Literal, Matrix, Q, add, mul, rational, symbols } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.logic.algorithms.lra_theory", () => {
  it("enc.add_from_cnf(cnf)", () => {
    const [y, x] = symbols('y x');
    const v1 = new EncodedCNF([[1, 2], [3, 4], [5, 6]], [[Q.lt(y, rational(1)), 1], [Q.gt(y, rational(1)), 2], [Q.eq(x, rational(0)), 3], [Q.eq(y, rational(1)), 4], [Q.lt(x, rational(0)), 5], [Q.gt(x, rational(0)), 6]]);
    const v2 = x;
    const v3 = rational(0);
    const v4 = Q.eq(v2, v3);
    const v5 = new Literal(v4, false);
    const v6 = y;
    const v7 = rational(1);
    const v8 = Q.eq(v6, v7);
    const v9 = new Literal(v8, false);
    const v10 = x;
    const v11 = rational(0);
    const v12 = Q.gt(v10, v11);
    const v13 = new Literal(v12, false);
    const v14 = x;
    const v15 = rational(0);
    const v16 = Q.lt(v14, v15);
    const v17 = new Literal(v16, false);
    const v18 = y;
    const v19 = rational(1);
    const v20 = Q.gt(v18, v19);
    const v21 = new Literal(v20, false);
    const v22 = y;
    const v23 = rational(1);
    const v24 = Q.lt(v22, v23);
    const v25 = new Literal(v24, false);
    const v26 = new CNF([[v5, v9], [v13, v17], [v21, v25]]);
    v1.addFromCnf(v26);
    expect(sympyStr(v1.addFromCnf(v26))).toBe('None');
  });
  it("Matrix(3, 3, var('a:i'))", () => {
    const [a, b, c, d, e, f, g, h, i] = symbols('a b c d e f g h i');
    expect(sympyStr(Matrix.row(a, b, c, d, e, f, g, h, i).reshape(3, 3))).toBe('Matrix([[a, b, c], [d, e, f], [g, h, i]])');
  });
  it("enc.from_cnf(cnf)", () => {
    const [x, z, y] = symbols('x z y');
    const v1 = new EncodedCNF([[1, 6], [2, 5], [3], [4]], [[Q.gt(add(x, mul(-1, z), mul(2, y)), rational(4)), 1], [Q.ge(add(x, mul(-1, z), mul(2, y)), rational(6)), 2], [Q.ge(x, rational(0)), 3], [Q.gt(rational(2), rational(1)), 4], [Q.le(add(x, y), rational(2)), 5], [Q.eq(add(x, y), rational(2)), 6]]);
    const v2 = add(x, y);
    const v3 = rational(2);
    const v4 = Q.eq(v2, v3);
    const v5 = new Literal(v4, false);
    const v6 = mul(-1, z);
    const v7 = mul(2, y);
    const v8 = add(x, v6, v7);
    const v9 = rational(4);
    const v10 = Q.gt(v8, v9);
    const v11 = new Literal(v10, false);
    const v12 = mul(-1, z);
    const v13 = mul(2, y);
    const v14 = add(x, v12, v13);
    const v15 = rational(6);
    const v16 = Q.ge(v14, v15);
    const v17 = new Literal(v16, false);
    const v18 = add(x, y);
    const v19 = rational(2);
    const v20 = Q.le(v18, v19);
    const v21 = new Literal(v20, false);
    const v22 = x;
    const v23 = rational(0);
    const v24 = Q.ge(v22, v23);
    const v25 = new Literal(v24, false);
    const v26 = rational(2);
    const v27 = rational(1);
    const v28 = Q.gt(v26, v27);
    const v29 = new Literal(v28, false);
    const v30 = new CNF([[v5, v11], [v17, v21], [v25], [v29]]);
    v1.fromCnf(v30);
    expect(sympyStr(v1.fromCnf(v30))).toBe('None');
  });
});
